export const meta = {
  name: 'slow-check',
  description: 'Three agents sleep 45s, then one reports',
  phases: [{ title: 'Wait' }, { title: 'Report' }],
}
phase('Wait')
const waits = await parallel([0, 1, 2].map(i => () => agent("Run `sleep 45` in Bash, then reply with exactly 'waited'.", { model: 'haiku', phase: 'Wait', label: `wait-${i + 1}` })))
phase('Report')
const report = await agent("Reply with exactly 'all waited'.", { model: 'haiku', phase: 'Report', label: 'report' })
return { waits, report }
